def grad_input_gen(
    self, init_tensors, use_cuda=False, max_time=None, **kwargs
) -> Optional[Dict[str, torch.Tensor]]:
    # TODO: trim the param. max_iter is not used; remove getenv
    if max_time is None:
        max_time = float(os.getenv("NNSMITH_GRAD_TIME", 0.5))

    inputs = {}
    for key, tensor in init_tensors.items():
        if tensor.data.dtype.is_floating_point:
            inputs[key] = torch.nn.parameter.Parameter(tensor.data.clone())
        else:
            inputs[key] = tensor.data

    self.enable_training(extra_trainable=inputs)

    last_check_intermediate_numeric = self.check_intermediate_numeric
    self.check_intermediate_numeric = True

    if use_cuda:
        for k in inputs:
            inputs[k] = inputs[k].cuda()
        self.use_cuda()

    sat_inputs = None
    st = time.time()
    self.iter_num = 0
    self.cur_loss_name = None
    while time.time() - st < max_time:
        self.training_reset()
        self.iter_num += 1

        try:
            _ = self(**inputs)
            if self.invalid_found_last:  # need_to_train
                self.backward()
            else:
                sat_inputs = {k: v.data for k, v in inputs.items()}
                break
        except ConstraintError as e:
            if __INPUT_FOUND_INF_MSG__ in str(e) or __INPUT_FOUND_NAN_MSG__ in str(
                e
            ):
                # flush NaN/Inf in inputs
                with torch.no_grad():
                    for inp in inputs.values():
                        inp.copy_(
                            torch.where(
                                inp.isnan().logical_or(inp.isinf()),
                                random_tensor(
                                    shape=inp.shape, dtype=inp.dtype.torch()
                                ).to(inp.device),
                                inp,
                            )
                        )
                continue
            TORCH_LOG.debug(e)
            break

    self.stop_training()
    if sat_inputs is None:
        TORCH_LOG.debug("[grad] no valid range found!!!")

    self.check_intermediate_numeric = last_check_intermediate_numeric
    return sat_inputs

def search(
    self, max_time_ms: int = None, max_sample: int = 1
) -> Tuple[int, Dict[str, torch.Tensor]]:
    n_try = 0
    sat_inputs = None
    start_time = time.time()

    while (
        max_time_ms is None or time.time() - start_time < max_time_ms / 1000
    ) and n_try < max_sample:
        if self.start_weights is not None and n_try < len(self.start_weights):
            self.apply_weights(self.net, self.start_weights[n_try])
        else:
            weight_sample = {}
            for name, param in self.net.named_parameters():
                weight_sample[name] = random_tensor(
                    param.shape, dtype=param.dtype, use_cuda=self.use_cuda
                )
            self.apply_weights(self.net, weight_sample)

        if self.start_inputs is not None and n_try < len(self.start_inputs):
            cur_input = self.start_inputs[n_try]
        else:
            cur_input = self.net.get_random_inps(use_cuda=self.use_cuda)

        res = self.search_one(cur_input, max_time_ms)
        n_try += 1
        if res is not None:
            sat_inputs = res
            break

    return n_try, sat_inputs

